data.css:
:root { color-scheme:light dark; --bg:#f3f6fc; --card:#fff; --text:#172a46; --muted:#51627a; --accent:#0055d4; --border:#d5dfed; --note:#eef4ff; }
* { box-sizing:border-box; }
html { scroll-padding-top:1.5rem; }
body { margin:0; background:var(--bg); color:var(--text); font:1.125rem/1.7 system-ui,-apple-system,"Segoe UI",sans-serif; overflow-wrap:anywhere; }
a { color:var(--accent); text-underline-offset:.2em; }
a:hover { text-decoration-thickness:.15em; }
a:focus-visible { outline:3px solid var(--accent); outline-offset:4px; border-radius:3px; }
.wrap { width:min(1160px,100% - 40px); margin-inline:auto; }
header { padding-block:44px 32px; }
.brand { font-weight:850; letter-spacing:.05em; text-decoration:none; font-size:1.35rem; }
.brand span { font-weight:400; }
.eyebrow { margin:48px 0 12px; color:var(--accent); font-weight:700; }
h1 { max-width:900px; font-size:clamp(2rem,4vw,3.5rem); line-height:1.12; letter-spacing:-.035em; margin:0 0 24px; }
.lead { max-width:780px; font-size:1.3rem; }
.meta,footer { color:var(--muted); font-size:1rem; }
code { font-family:ui-monospace,monospace; font-size:.9em; }
.layout { display:grid; grid-template-columns:230px minmax(0,1fr); gap:32px; align-items:start; }
nav { position:sticky; top:24px; padding:20px; background:var(--card); border:1px solid var(--border); border-radius:20px; }
nav h2 { margin:0 0 12px; font-size:1.05rem; }
nav a { display:block; padding:10px 0; font-size:1rem; text-decoration:none; }
main { min-width:0; }
section { padding:28px 32px; background:var(--card); border:1px solid var(--border); border-radius:24px; margin-bottom:20px; }
h2 { font-size:1.5rem; line-height:1.3; margin:0 0 20px; letter-spacing:-.02em; }
p { margin:0 0 18px; }
p:last-child { margin-bottom:0; }
dl { margin:0; } dt { font-weight:750; } dd { margin:6px 0 22px; }
.notice { background:var(--note); border-left:4px solid var(--accent); padding:20px; border-radius:0 12px 12px 0; }
footer { padding-block:32px 48px; }
.skip { position:absolute; left:20px; top:-100px; padding:12px; background:var(--card); z-index:2; }
.skip:focus { top:12px; }
@media(max-width:800px) { .layout { grid-template-columns:1fr; gap:20px; } nav { position:static; } nav a { display:inline-block; margin-right:18px; } header { padding-top:28px; } .eyebrow { margin-top:32px; } }
@media(max-width:480px) { .wrap { width:calc(100% - 24px); } section { padding:24px 20px; border-radius:18px; } body { font-size:1.08rem; } }
@media(prefers-color-scheme:dark) { :root { --bg:#0d1523; --card:#172236; --text:#f0f5ff; --muted:#b5c4dd; --accent:#8ebaff; --border:#344660; --note:#203653; } }
@media print { :root { --bg:#fff; --card:#fff; --text:#000; --muted:#333; --accent:#000; --border:#bbb; } nav,.skip { display:none; } .layout { display:block; } .wrap { width:100%; } section { break-inside:avoid; padding:15px; } }
